-- ==========================================================================
-- B4 FOLLOW-ON FIX (uncertainty): uncertainty: duplicate question rewritten into a new question
--
-- Courses: uncertainty. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/uncertainty.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql uncertainty. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- uncertainty beginner final - ord 37
  select case when md5(prompt) = '0a52ec4b85ab6dcdc127be7c51025548' and md5(coalesce(explanation, '')) = 'c5b5a271dd62883071bddb77a28b0d0c' and md5(options::text) = md5('["As a Low case P90 of 62.1713, a Best case P50 of 73.3297 and a High case P10 of 85.5912, as for any outcome of a model.", "As P10 62.1713, P50 73.3297 and P90 85.5912, since for a price the labels simply follow the sorted order of the sample.", "As a Base of 62.1713, a median of 73.3297 and an upside of 85.5912, spread around the stated-median breakeven of 71.6277.", "As the 10th percentile, median and 90th percentile of breakeven price, because a higher breakeven is worse."]'::jsonb::text) and answer_index = 3 then 'old'
              when md5(prompt) = '405194336602b0ac779accde3a82b4dd' and md5(coalesce(explanation, '')) = '3628aa9ee4d45e72ba59abc8d241537e' and md5(options::text) = md5('["20 of 20: capex is split half and half over 2027 and 2028, and an even split keeps both years'' taxable income above zero.", "18 of 20: the last two years pay 0.0000, because by then the declined volume no longer covers the opex and the royalty.", "16 of 20: the losses of 2027 and 2028 are carried forward and shelter 2029 and 2030 as well, before tax resumes in 2031.", "18 of 20: capex is expensed in 2027 and 2028, so taxable income is negative there and those two years pay 0.0000."]'::jsonb::text) and answer_index = 3 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'uncertainty' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 37 and active;
  if v_state is null then raise exception 'B4 fix uncertainty refused: no row for uncertainty beginner final - ord 37'; end if;
  if v_state = 'other' then raise exception 'B4 fix uncertainty refused: uncertainty beginner final - ord 37 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Across ISIALA''s twenty ledger rows tax is positive in some years and 0.0000 in others. How many years pay tax, and what sets the others to 0.0000?', options = '["20 of 20: capex is split half and half over 2027 and 2028, and an even split keeps both years'' taxable income above zero.", "18 of 20: the last two years pay 0.0000, because by then the declined volume no longer covers the opex and the royalty.", "16 of 20: the losses of 2027 and 2028 are carried forward and shelter 2029 and 2030 as well, before tax resumes in 2031.", "18 of 20: capex is expensed in 2027 and 2028, so taxable income is negative there and those two years pay 0.0000."]'::jsonb,
           answer_index = 3, explanation = 'Capex is expensed in the year it is spent, so revenue less royalty, capex and opex is negative in 2027 and 2028 and tax is 0.0000 there. No loss is carried forward, so 2029 pays 35 percent of its own positive base, 19.3660, and tax is positive in 18 of 20 years.'
     where app_slug = 'uncertainty' and tier = 'beginner' and scope = 'final' and module_key is not distinct from null and ord = 37 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix uncertainty refused: uncertainty beginner final - ord 37 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'uncertainty' and active;
  if v_total <> 396 then raise exception 'B4 fix uncertainty refused: uncertainty holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix uncertainty: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
